        actions([['saveEmby','\u4FDD\u5B58\u670D\u52A1\u5668','primary'],['testEmbyEdit','\u6D4B\u8BD5\u767B\u5F55','secondary'],['newEmby','\u65B0\u589E\u670D\u52A1\u5668','primary'],['deleteEmbyEdit','\u5220\u9664\u670D\u52A1\u5668','danger']]) +
        '<div class="hint">EmbyDiy \u901A\u8FC7 ext \u91CC\u7684 embynumber \u8BFB\u53D6\u8FD9\u91CC\u7684\u670D\u52A1\u5668\u5E8F\u53F7\u3002</div>';
